/// Every scheme this build ships, for a settings panel to offer.
pub static ALL: &[&Palette] = &[&CLASSIC_G10, &CLASSIC_G24, &CLASSIC, &GOTHAM];

/// What a component draws with when nothing selects a scheme.
pub static DEFAULT: &Palette = &CLASSIC;

/// The scheme a config file or a `--palette` flag names.
///
/// `None` for an unknown id rather than a fallback: only the caller knows
/// whether that deserves a warning and [`DEFAULT`], or is a hard error.
pub fn by_id(id: &str) -> Option<&'static Palette> {
    ALL.iter().copied().find(|p| p.id == id)
}
